package net.officefloor.hq.app.payment;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The payments a client has made against an invoice, oldest first. */
@RestController
@RequestMapping("/api/projects/{projectId}/invoices/{invoiceId}/payments")
public class InvoicePaymentController {

    private final PaymentService service;

    public InvoicePaymentController(PaymentService service) {
        this.service = service;
    }

    @GetMapping
    public List<PaymentResponse> list(@PathVariable Long projectId, @PathVariable Long invoiceId) {
        return service.list(projectId, invoiceId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PaymentResponse record(@PathVariable Long projectId, @PathVariable Long invoiceId,
            @Valid @RequestBody PaymentRequest request) {
        return service.record(projectId, invoiceId, request);
    }
}
package net.officefloor.hq.app.fx;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.currency.CurrencyService;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Keeps the history of exchange rates, and converts foreign amounts into the home currency at the rate in
 * effect on a given date.
 */
@Service
public class FxRateService {

    private final FxRateRepository rates;
    private final CurrencyService currencies;
    private final SettingsService settings;
    private final Audit audit;

    public FxRateService(FxRateRepository rates, CurrencyService currencies, SettingsService settings, Audit audit) {
        this.rates = rates;
        this.currencies = currencies;
        this.settings = settings;
        this.audit = audit;
    }

    /** The recorded rates, by currency with the most recent first. */
    @Transactional(readOnly = true)
    public List<FxRateResponse> list() {
        return rates.findAllByOrderByCurrencyAscRateDateDescIdDesc().stream().map(FxRateResponse::from).toList();
    }

    /**
     * Records the currency's rate from the date, recording it in the audit log. A currency has at most one
     * rate a day, and the home currency needs none.
     */
    @Transactional
    public FxRateResponse record(FxRateRequest request) {
        String currency = request.currency().trim().toUpperCase(Locale.ROOT);
        if (!currencies.exists(currency)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
        }
        if (currency.equals(settings.homeCurrency())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The home currency needs no exchange rate");
        }
        if (rates.existsByCurrencyAndRateDate(currency, request.date())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rate for this currency on this date already exists");
        }
        FxRate saved = rates.saveAndFlush(new FxRate(currency, request.date(), request.rate()));
        audit.record("FX_RATE_RECORDED id=" + saved.getId() + " currency=" + currency + " date=" + saved.getRateDate()
                + " rate=" + saved.getRate().stripTrailingZeros().toPlainString());
        return FxRateResponse.from(saved);
    }

    /**
     * The amount in the home currency, converted at the currency's rate on the date (its latest rate dated
     * on or before it); empty when the currency has no rate by then.
     */
    @Transactional(readOnly = true)
    public Optional<BigDecimal> toHome(String currency, LocalDate date, BigDecimal amount) {
        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date)
                .map(r -> amount.multiply(r.getRate()).setScale(2, RoundingMode.HALF_UP));
    }

    /**
     * The amount converted from one currency into another at the rates in effect on the date, going through the
     * home currency; empty when either foreign currency has no rate by then. The same currency converts as is.
     */
    @Transactional(readOnly = true)
    public Optional<BigDecimal> convert(String from, String to, LocalDate date, BigDecimal amount) {
        if (from.equals(to)) {
            return Optional.of(amount.setScale(2, RoundingMode.HALF_UP));
        }
        Optional<BigDecimal> fromRate = rateToHome(from, date);
        Optional<BigDecimal> toRate = rateToHome(to, date);
        if (fromRate.isEmpty() || toRate.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(amount.multiply(fromRate.get()).divide(toRate.get(), 2, RoundingMode.HALF_UP));
    }

    /** How many units of the home currency one unit of the currency is worth on the date. */
    private Optional<BigDecimal> rateToHome(String currency, LocalDate date) {
        if (currency.equals(settings.homeCurrency())) {
            return Optional.of(BigDecimal.ONE);
        }
        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date).map(FxRate::getRate);
    }
}
package net.officefloor.hq.app.fx;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface FxRateRepository extends JpaRepository<FxRate, Long> {

    /** The currency's rate in effect on the date: its latest rate dated on or before it. */
    Optional<FxRate> findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(String currency, LocalDate date);

    /** Whether the currency already has a rate dated on the day. */
    boolean existsByCurrencyAndRateDate(String currency, LocalDate rateDate);

    /** The rate history: by currency, the most recent rate first. */
    List<FxRate> findAllByOrderByCurrencyAscRateDateDescIdDesc();
}

